/* Keep the small pencil box inside a larger pointer and touch target. */
.ink-ledger .ledger-tick{position:relative;display:inline-grid;place-items:center;width:28px;height:30px;flex:none;cursor:pointer}
.ink-ledger .ledger-tick input[type=checkbox]{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;z-index:1;cursor:pointer}
.ink-ledger .ledger-tick::before{content:"";width:14px;height:14px;box-sizing:border-box;background:rgb(231 223 239 / .046);backdrop-filter:blur(2px);border:1.2px solid #bfadd0;border-radius:3px 4px 2px 4px;transform:rotate(-3deg)}
.ink-ledger .ledger-tick:has(:checked)::before{background:#c9afd8;border-color:#c9afd8}
.ink-ledger .ledger-tick:has(:checked)::after{content:"";position:absolute;width:9px;height:5px;box-sizing:border-box;border-left:2px solid #302733;border-bottom:2px solid #302733;transform:translateY(-1px) rotate(-47deg)}
.ink-ledger .ledger-tick:has(:focus-visible)::before{outline:2px solid var(--jp-accent);outline-offset:3px}
.ink-ledger .dwh-todos .dwh-chain-row:has(.ledger-tick :checked) .ink-item-text{color:var(--jp-muted);background:none;text-decoration:line-through;text-decoration-color:#a297a4}
